  "confidence": "high",
  "uncertainties": [],
  "risk": {
    "level": "medium",
    "touches": ["rpc_api", "wallet"],
    "why": "Alters RPC error message strings, which could break external applications or automated test scripts that rely on exact error string matching."
  }
}
